/**
 * The store console's chart of today's slots (PRD-031): one bar per slot, its height the places left. The console
 * draws it with chart.js: slotChartConfig([{ start: '18:00', end: '19:00', left: 2 }]) → a chart.js bar config.
 */
import { formatSlot } from './format-slot.js';

export const slotChartConfig = (slots) => ({
  type: 'bar',
  data: { labels: slots.map((s) => formatSlot(s.start, s.end)), datasets: [{ label: 'Places left', data: slots.map((s) => s.left) }] },
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { slotChartConfig } from '../slot-chart.js';

test('slotChartConfig: one bar per slot, its height the places left', () => {
  const c = slotChartConfig([{ start: '18:00', end: '19:00', left: 2 }, { start: '19:00', end: '20:00', left: 0 }]);
  assert.deepEqual(c.data.labels, ['18:00–19:00', '19:00–20:00']);
  assert.deepEqual(c.data.datasets[0].data, [2, 0]);
});
